63| def validate(mods):
64|     errs = []
65|     owner = {}
66|     for rid, m in mods.items():
67|         for room_id in m.get("rooms", {}):
68|             if room_id in owner:
69|                 errs.append("duplicate room id across modules: " + room_id)
70|             owner[room_id] = rid
71|     for rid, m in mods.items():
72|         if m.get("start_room") and m.get("rooms"):
73|             if m["start_room"] not in m["rooms"]:
74|                 errs.append("%s start_room missing" % rid)
75|         for room in m.get("rooms", {}).values():
76|             for dst in room.get("exits", {}).values():
77|                 if dst not in owner:
78|                     errs.append("unresolved exit: %s -> %s" % (room["id"], dst))
79|     # agreed invariants wired?
80|     ford = mods["adventure_2d6_stub"]["rooms"]["river_ford"]
81|     if ford["exits"].get("north") != "gallery":
82|         errs.append("loop-closes NOT wired: river_ford.north != gallery")
83|     dl = mods["audit_dungeon"]["rooms"]["doctrine_library"]
84|     if dl["exits"].get("lens_gate") != "garage_gate":
85|         errs.append("lens-count-gate NOT wired")
86|     got_lenses = [r for r in mods["riddler_optics"]["rooms"] if r in LENS_ROOMS]
87|     if len(got_lenses) != 10:
88|         errs.append("expected 10 lens rooms, found %d" % len(got_lenses))
89|     return errs, owner
