92| def beta0(mods):
93|     adj = {r: set() for r in REGIONS}
94|     owner = {}
95|     for rid, m in mods.items():
96|         for room_id in m.get("rooms", {}):
97|             owner[room_id] = rid
98|     for rid, m in mods.items():
99|         for room in m.get("rooms", {}).values():
100|             for dst in room.get("exits", {}).values():
101|                 other = owner.get(dst)
102|                 if other and other != rid:
103|                     adj[rid].add(other)
104|                     adj[other].add(rid)  # undirected: forward-only undercounts merges
105|     seen, n = set(), 0
106|     for r in REGIONS:
107|         if r in seen:
108|             continue
109|         n += 1
110|         q = deque([r])
111|         while q:
112|             u = q.popleft()
113|             if u in seen:
114|                 continue
115|             seen.add(u)
116|             q.extend(adj[u] - seen)
117|     return n
