120| ENGINE = r"""
121| // ================= THE WALKER (one engine, no second data format) ==========
122| const OWNER = {};
123| for (const [mod, m] of Object.entries(MODULES))
124|   for (const rid of Object.keys(m.rooms || {})) OWNER[rid] = mod;
125| 
126| const state = {
127|   mod: "adventure_2d6_stub",          // neutral start: crossroads — descent contested
128|   room: "crossroads",
129|   lenses: [],                          // lens room ids collected
130|   out_height: 0,                       // water OUT tank height (0..3)
131|   valve_a: false, valve_b: false, ticks: 0,
132|   refraction: false,                   // OUT.height carried as refractive index
133|   disputed: [],                        // kifu rows flagged DISPUTED
134|   kifu: [],                            // every move, session record
135|   summoned: {}
136| };
137| 
138| function room() { return MODULES[state.mod].rooms[state.room]; }
139| function kifu(line, flag) {
140|   state.kifu.push({ ts: new Date().toISOString(), mod: state.mod, room: state.room,
141|                     line, flag: flag || null });
142|   if (flag === "DISPUTED") state.disputed.push(line);
143| }
144| 
145| function render() {
146|   try { _render(); } catch (e) {
147|     state.kifu.push({ ts: new Date().toISOString(), mod: state.mod,
148|       room: state.room, line: "render error: " + e.message, flag: "DISPUTED" });
149|   }
150|   document.getElementById("kifu").textContent =
151|     state.kifu.slice(-14).map(k => k.ts.slice(11, 19) + " " + k.line +
152|       (k.flag ? " [" + k.flag + "]" : "")).join("\n");
153|   renderQuests();
154|   const hints = { gallery: "open valve a", source_cistern: "open valve a",
155|     out_cistern: "wait", fractal_maze: "ride the refraction",
156|     riddler_engram: "summon pratchett", audit_dungeon: "walk to doctrine_library" };
157|   document.getElementById("cmd").placeholder =
158|     hints[state.mod + "/" + state.room] || hints[state.mod] || hints[state.room] || "pour bucket";
159| }
160| 
161| function renderQuests() {
162|   const q = [
163|     { done: state.out_height >= 3, text: "fill the water tanks at the Clear Pipes keep (open valve a, open valve b, wait x3)" },
164|     { done: state.refraction, text: "carry the height — you are now carrying the refractive index" },
165|     { done: state.lenses.length >= 10, text: "gather the 10 lenses in the optics garage (walk all ten lens rooms)" },
166|     { done: state.lenses.length >= 10 && state.mod === "audit_dungeon", text: "open the library's lens gate (audit dungeon -> the garage beyond)" },
167|     { done: state.kifu.some(k => /loop witnessed/.test(k.line)), text: "witness the ford loop (river ford -> the gallery -> home)" }
168|   ];
169|   document.getElementById("quests").innerHTML = q.map(x =>
170|     (x.done ? "\u2611 " : "\u2610 ") + x.text).join("<br>");
171| }
