173| function _render() {
174|   const r = room();
175|   const lensRow = "lenses: " + state.lenses.length + "/10";
176|   const waterRow = "valve A: " + (state.valve_a ? "OPEN" : "closed") +
177|                    " · valve B: " + (state.valve_b ? "OPEN" : "closed") +
178|                    " · OUT.height: " + state.out_height + "/3" +
179|                    (state.refraction ? " · refractive index CARRIED" : "");
180|   let exits = Object.entries(r.exits || {}).map(([k, d]) => {
181|     const target = OWNER[d] ? d + "  [" + OWNER[d] + "]" : d + " (broken)";
182|     let lock = "";
183|     if (d === "leaf_gate" && !state.refraction)
184|       lock = "  ⛔ water-feeds-field: leaf_gate needs OUT.height (the refractive index)";
185|     if (state.room === "doctrine_library" && d === "lens_gate" && state.lenses.length < 10)
186|       lock = "  ⛔ lens-count-gate: " + state.lenses.length + "/10 lenses";
187|     return '<button data-exit="' + d + '" ' + ((lock || target.includes("(broken)")) ? "disabled" : "") +
188|            '>' + k + ' → ' + target + lock + '</button>';
189|   }).join("<br>");
190|   const hooks = (r.hooks || []).map(h => "· " + h).join("<br>");
191|   const contested = (state.mod === "water_computer" || state.mod === "fractal_maze")
192|     ? '<div class=" contested">CONTESTED EDGE (RIB): gate style — valve heights (Grok) vs computed flag (DeepSeek). Both readouts shown; neither rules. Tiebreak gated on operator GO.</div>' : "";
193|   document.getElementById("view").innerHTML =
194|     '<div class="mod">' + state.mod + " / " + state.room + "</div>" +
195|     "<h2>" + r.name + "</h2><p>" + (r.desc || "") + "</p>" +
196|     '<div class="meters">' + lensRow + " · " + waterRow + "</div>" +
197|     contested +
198|     "<h3>exits</h3>" + (exits || "<i>none</i>") +
199|     "<h3>hooks</h3><div>" + (hooks || "<i>—</i>") + "</div>";
200| }
