202| function gotoRoom(dst) {
203|   const [mod, rid] = resolve(dst);
204|   if (!mod) { kifu("REFUSED broken exit " + dst, "DISPUTED"); render(); return; }
205|   // ---- AGREED GATES (RIB_CATHEDRAL_WORLD_V1) ----
206|   if (dst === "leaf_gate" && !state.refraction) {
207|     kifu("REFUSED leaf_gate without OUT.height — water-feeds-field", "DISPUTED");
208|     render(); return;
209|   }
210|   if (state.room === "doctrine_library" && dst === "garage_gate" &&
211|       state.lenses.length < 10) {
212|     kifu("REFUSED lens_gate at " + state.lenses.length + "/10 — lens-count-gate", "DISPUTED");
213|     render(); return;
214|   }
215|   kifu("move " + state.mod + "." + state.room + " -> " + dst);
216|   state.mod = mod; state.room = rid;
217|   onEnter();
218|   render();
219| }
