221| function resolve(dst) {
222|   if (OWNER[dst]) return [OWNER[dst], dst];
223|   for (const [mod, m] of Object.entries(MODULES))
224|     if ((m.rooms || {})[dst]) return [mod, dst];
225|   return [null, null];
226| }
