228| function onEnter() {
229|   const r = room();
230|   // lens pickup
231|   if (LENS_ROOMS.includes(state.room) && !state.lenses.includes(state.room)) {
232|     state.lenses.push(state.room);
233|     kifu("lens collected: " + state.room + " (" + state.lenses.length + "/10)");
234|     if (state.lenses.length === 10)
235|       kifu("TEN LENSES — lens-count-gate OPEN (audit doctrine_library -> garage_gate)");
236|   }
237|   // the loop, witnessed
238|   if (state.room === "gallery" && state.kifu.some(k => k.room === "river_ford"))
239|     kifu("loop witnessed: the ford runs to the gallery — loop-closes HOLDS");
240| }
