242| function act(cmd) {
243|   const c = cmd.trim().toLowerCase();
244|   if (c === "open valve a" && state.mod === "water_computer") state.valve_a = true;
245|   else if (c === "open valve b" && state.mod === "water_computer") state.valve_b = true;
246|   else if (c === "wait" && state.mod === "water_computer") {
247|     state.ticks++;
248|     if (state.valve_a) state.out_height = Math.min(3, state.out_height + 1);
249|     if (state.valve_b && state.out_height > 0) state.out_height = Math.min(3, state.out_height + 1);
250|     kifu("wait — gravity ticks; OUT.height=" + state.out_height);
251|     if (state.out_height >= 3 && !state.refraction) {
252|       state.refraction = true;
253|       kifu("OUT.height=3 carried as the refractive index — water-feeds-field satisfied");
254|     }
255|     render(); return;
256|   } else if (c === "pour bucket") {
257|     kifu("pour bucket REFUSED — mechanism-is-the-answer: bucket-poured water is not computation", "DISPUTED");
258|     render(); return;
259|   } else if (c.startsWith("summon ")) {
260|     const who = c.slice(7).toUpperCase();
261|     const seat = ENGRAM_SEATS.find(s => s.seat === who || s.alias === c.slice(7));
262|     if (!seat) { kifu("no such seat: " + who); render(); return; }
263|     state.summoned[seat.seat] = true;
264|     kifu("summoned " + seat.seat + " (" + seat.alias + ")");
265|     alert(seat.seat + " — " + seat.alias + ':\n"' + seat.riddle + '"');
266|     render(); return;
267|   } else { kifu("no such act: " + c); render(); return; }
268|   kifu("act: " + c); render();
269| }
